import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    score = 0
    opp_c = 0
    my_c = 0
    last_opp = None
    for i, (a, b) in enumerate(history):
        opp_c += (b == 'C')
        my_c += (a == 'C')
        last_opp = b

    if n >= 2:
        prev_a, prev_b = history[-2]
        if prev_a == 'D' and prev_b == 'C':
            return 'D'
        if prev_a == 'D' and prev_b == 'D':
            return 'C' if rng.random() < 0.35 else 'D'
        if prev_a == 'C' and prev_b == 'D':
            return 'D' if rng.random() < 0.7 else 'C'
        if prev_a == 'C' and prev_b == 'C':
            if n < 90:
                return 'C'
            return 'C' if rng.random() < 0.9 else 'D'

    return 'C'
